import{_ as l,o as t,c as i,a4 as a}from"./chunks/framework.DzJZdBQK.js";const h=JSON.parse('{"title":"写作课作业-120","description":"","frontmatter":{"date":"2021-05-03T22:16:28","title":"写作课作业-120","categories":["写作","作业","一年顶十年"],"tags":["写作","作业","一年顶十年"]},"headers":[{"level":2,"title":"知识点","slug":"知识点","link":"#知识点","children":[]},{"level":2,"title":"我的思考","slug":"我的思考","link":"#我的思考","children":[]}],"relativePath":"posts/homework/120.md","filePath":"posts/homework/120.md"}'),o={name:"posts/homework/120.md"};function r(p,e,s,n,_,c){return t(),i("div",null,[...e[0]||(e[0]=[a('<blockquote><p>《一年顶十年》之《团队 如何打造极有战斗力的小团队》</p></blockquote><h2 id="知识点" tabindex="-1">知识点 <a class="header-anchor" href="#知识点" aria-label="Permalink to &quot;知识点&quot;">​</a></h2><ul><li>跟我一起做事的人，必须要有自己的定位，并且不断地学习、实践、总计、分享，努力提升自己的专业能力。定位清晰后，注意力会更聚焦，自我要求会更高，成长速度会更快，大家也能把工作做得更好。</li><li>选人，首先要看一个人做事是不是持续靠谱；其次还要看“五心”——野心，平常心，感恩心，敬畏心，专心。</li><li>每天早晚集体朗读，一方面，e快船让工作更有仪式感，让大家的状态变得更好；另一方面，还能做大家牢记工作原则和原理，从而更好地践行。</li><li>复盘，大家可以更好地知道自己一天到晚在忙什么，有什么收获，有哪些不足，从而想得更清楚，活得更明白。另一方面，我要求所有人把复盘的内容发到核心团队群里，其他人都能看到。</li><li>最好的团建，就是带着大家一起打胜仗。</li><li>如果你想让自己的团队成员很有狼性，就不要只给大家吃草。狼是要吃肉的，而且还要吃够，这样才能更有战斗力。</li><li>要想让团队的某个人成长得更快，有三个字非常重要——让他上。</li><li>我们团队一直坚持“老带新”。</li><li>老板有一个很重要的角色：教练。激发潜力、鼓舞士气，在合适的时候提供必要的支持，让大家能更好的胜任工作，更好地成长。要当好教练，有一种能力很重要，那就是提问能力。通过提出好问题，你可以引导团队成员进行高质量的思考，从而理清思路，把事情做好。由于要教别人，他自然会更努力地去学，而且会学得更好。</li></ul><h2 id="我的思考" tabindex="-1">我的思考 <a class="header-anchor" href="#我的思考" aria-label="Permalink to &quot;我的思考&quot;">​</a></h2><p>最好的团建，就是带着大家一起打胜仗。</p><p>参加了公司包场看电影的一次团建活动，我认为是没起到到团建的作用，勉强让大家放松一下。为什么会这么想呢？团建重要的一个目的是增加大家的了解，促进工作中的协调和默契。看电影——大家陆陆续续的来，三三两两的坐，安安静静地看，挥一挥手各回各家。整个活动没有什么交流，就是聊一聊对电影的看法的时间都没能安排。</p><p>记得得到的罗振宇说过，如果办演讲的时候是全员一起上的，这应该是一个大规模的战斗。</p><p>要想上团队的某人人成长得更快，有三个字非常重要——让他上。自己刚加入公司不久就被安排去出差去给一个客户升级系统，升级系统的过程中还碰到一些比较棘手的问题，之后在碰到系统问题不害怕了。</p><hr><p>欢迎联系我</p><p>微信号 ：Crazy_Airhead</p><p>Mixin ID : 1091586</p><p>定投课堂邀请码：6DYMBFP061</p><p>李笑来写作课邀请码：38MDGFYZK8</p><p>水龙头邀请码：FDJQHJ</p>',15)])])}const u=l(o,[["render",r]]);export{h as __pageData,u as default};
